function fmtDate(d){return new Date(d+'T12:00:00').toLocaleDateString(currentLang,{day:'2-digit',month:'short'});}
function eventCard(e){const x=e.loc[currentLang]||e.loc.en;return `<article class="event-card ${e.kind}" id="event-${e.id}"><div class="event-meta"><span class="date-chip">${fmtDate(e.start)} — ${fmtDate(e.end)}</span><span class="badge ${e.kind}">${t(e.kind)}</span></div><h3>${x.title}</h3><p>${x.desc}</p><div class="event-block loot"><strong>${t('coupon')}</strong><p>${x.loot}</p></div><div class="event-block tip"><strong>${t('tips')}</strong><p>${x.tip}</p></div></article>`;}
function renderIndex(){const grid=document.querySelector('#events-grid');if(!grid)return;const filter=document.querySelector('.filter.active')?.dataset.filter||'all', q=(document.querySelector('#event-search')?.value||'').toLowerCase();const list=EVENTS.filter(e=>(filter==='all'||e.kind===filter)&&((e.loc[currentLang]||e.loc.en).title.toLowerCase().includes(q)||e.loot.toLowerCase().includes(q)));grid.innerHTML=list.map(eventCard).join('');const cal=document.querySelector('#calendar-grid');cal.innerHTML=EVENTS.map(e=>`<button class="day-pill ${e.kind}" onclick="document.querySelector('#event-${e.id}').scrollIntoView({behavior:'smooth',block:'center'})"><b>${e.start.slice(8)}</b><span>${(e.loc[currentLang]||e.loc.en).title.replace(/Operation|Операция|Opération|Operation|Operación|行动/gi,'').trim().slice(0,13)}</span></button>`).join('');}
function initIndex(){if(!document.querySelector('#events-grid'))return;document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderIndex();});document.querySelector('#event-search').oninput=renderIndex;renderIndex();let next=EVENTS.find(e=>new Date(e.start)>new Date())||EVENTS[0];const draw=()=>{const x=next.loc[currentLang]||next.loc.en;document.querySelector('#next-name').textContent=x.title;document.querySelector('#next-date').textContent=fmtDate(next.start)+' — '+fmtDate(next.end);let n=Math.max(0,new Date(next.start+'T12:00:00')-new Date()), v=[Math.floor(n/864e5),Math.floor(n/36e5)%24,Math.floor(n/6e4)%60,Math.floor(n/1e3)%60];['days','hours','minutes','seconds'].forEach((_,i)=>document.querySelector('#cd-'+_).textContent=String(v[i]).padStart(2,'0'));};draw();setInterval(draw,1000);}
const VEH=[['M109A6','USA','Ground','7.0','Self-propelled artillery with a flexible support loop.','18–30 GJN'],['F-5C Anniversary','USA','Air','10.7','Fast strike fighter: use altitude and short attack windows.','25–45 GJN'],['T-80U Holiday','USSR','Ground','10.7','Heavy armour and a stabilizer reward deliberate pushes.','30–55 GJN'],['PT-811','USA','Naval','3.7','Fast torpedo boat: contest caps, disengage early.','8–15 GJN']];
function renderVehicles(){const el=document.querySelector('#vehicle-list');if(!el)return;el.innerHTML=VEH.map(v=>`<article class="vehicle-card panel"><div class="vehicle-code">${v[0].slice(0,2)} // ${v[3]}</div><h3>${v[0]}</h3><p class="muted">${v[1]} · ${v[2]}</p><p>${v[4]}</p><div class="vehicle-foot"><span>BR ${v[3]}</span><strong>${v[5]}</strong></div></article>`).join('');}
function initCalc(){const b=document.querySelector('#calc-btn');if(!b)return;const run=()=>{const h=+document.querySelector('#hours-day').value,n=+document.querySelector('#points-needed').value,m=document.querySelector('#farm-mode').value,stats={AB:[220,8],RB:[340,11],SB:[480,15]}[m],days=Math.ceil(n/(stats[0]*(h*60/stats[1]))),el=document.querySelector('#calc-result');el.innerHTML=`<strong>${days} ${t('days').toLowerCase()}</strong><span>${Math.ceil(days*h)} h total · ${stats[0]} ${t('points')} / ${stats[1]} min</span><em>${days<=7?t('worth'):days<=14?t('risky'):t('avoid')}</em>`;};b.onclick=run;run();}
function initContact(){const f=document.querySelector('#contact-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();const n=document.querySelector('#contact-name').value,em=document.querySelector('#contact-email').value,msg=document.querySelector('#contact-message').value;location.href=`mailto:jean.potato@example.com?subject=WT Events 2026 — ${encodeURIComponent(n)}&body=${encodeURIComponent(msg+'\n\nReply: '+em)}`;document.querySelector('#form-status').textContent=t('success');};}
window.pageRender=()=>{applyLang();renderIndex();renderVehicles();initCalc();initContact();};document.addEventListener('DOMContentLoaded',()=>{initIndex();renderVehicles();initCalc();initContact();});
